import { readFileSync } from 'node:fs'

const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
let mode = args[0]
let workers = 0
if (!((mode === 'waves' || mode === 'explain') && args.length === 1) && !(mode === 'pack' && args.length === 2)) {
  fail('error: usage: cli.js waves|explain|pack <workers>')
}
if (mode === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})
for (const x of depUses) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort()
const dl = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort()]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const d of dl.get(u)) {
    if (state.get(d) === 1) {
      const cyc = stack.slice(stack.indexOf(d)).concat(d)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!state.has(d)) dfs(d)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.has(k)) dfs(k)

const start = new Map()
const finish = new Map()
const depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0
  let dp = 0
  for (const d of dl.get(u)) {
    calc(d)
    s = Math.max(s, finish.get(d))
    dp = Math.max(dp, depth.get(d) + 1)
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, dp)
}
names.forEach(calc)
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((g, i) => (out += `wave ${i}: ${g.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
  const users = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of dl.get(k)) users.get(d).push(k)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const v of users.get(u)) m = Math.max(m, pr(v))
    prio.set(u, cost.get(u) + m)
    return prio.get(u)
  }
  names.forEach(pr)
  const freeAt = Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  const pending = new Set(names)
  let t = 0
  let makespan = 0
  while (pending.size) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of names) {
        if (!pending.has(k)) continue
        if (!dl.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best)) best = k
      }
      if (best === null) break
      pending.delete(best)
      const f = t + cost.get(best)
      fin.set(best, f)
      freeAt[wi] = f
      ran[wi].push(`${best}@${t}-${f}`)
      makespan = Math.max(makespan, f)
    }
    if (!pending.size) break
    t = Math.min(...freeAt.filter((f) => f > t))
  }
  ran.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
